    if (['manage-note', 'manage-tag', 'manage-ready', 'tag-click', 'tag-suggest', 'tag-combined'].includes(params.get('state'))) {
      document.querySelector('#manage-note').value = 'Use this for the typography workshop';
    }
    if (params.get('state') === 'manage-tag' || params.get('state') === 'manage-ready') addTag('design');
    function showManagedResult(note, tags) {
      document.querySelector('#manage-editor').style.display = 'none';
      document.querySelector('#manage-card').style.display = 'grid';
      document.querySelector('#manage-confirmation').style.display = 'flex';
      const noteDisplay = document.querySelector('#card-note');
      noteDisplay.querySelector('span').textContent = note;
      noteDisplay.style.display = note ? 'block' : 'none';
      const tagDisplay = document.querySelector('#card-tags');
      tagDisplay.innerHTML = '';
      for (const tag of tags) {
        const chip = document.createElement('span');
        chip.className = 'tag-chip';
        chip.textContent = tag;
        tagDisplay.appendChild(chip);
      }
      tagDisplay.style.display = tags.length ? 'flex' : 'none';
    }
    document.querySelector('#save-managed').addEventListener('click', () => {
      const note = document.querySelector('#manage-note').value.trim();
      const tags = [...document.querySelectorAll('.tag-entry .tag-chip > span')].map(item => item.textContent);
      showManagedResult(note, tags);
      history.replaceState({}, '', '?state=managed');
    });
    if (params.get('state') === 'managed') {
      showManagedResult('Use this for the typography workshop', ['design']);
    }
    if (params.get('state') === 'tag-click') {
      const tagInput = document.querySelector('#manage-tag');
      tagInput.value = 'design';
      document.querySelector('#tag-help').textContent = 'Type a tag, then add it';
      const addButton = document.createElement('button');
      addButton.type = 'button';
      addButton.className = 'tag-add-button';
      addButton.textContent = 'Add';
      addButton.addEventListener('click', () => addTag(tagInput.value));
      document.querySelector('.tag-entry').appendChild(addButton);
    }
    if (params.get('state') === 'tag-suggest') {
      const tagEntry = document.querySelector('.tag-entry');
      tagEntry.innerHTML = '<div class="tag-suggestions"><button type="button" class="tag-suggestion">design</button><button type="button" class="tag-suggestion">reading</button><button type="button" class="tag-suggestion">research</button></div>';
      document.querySelector('#tag-help').textContent = 'Choose a suggested tag';
      for (const button of document.querySelectorAll('.tag-suggestion')) {
        button.addEventListener('click', () => {
          const label = button.textContent;
          tagEntry.innerHTML = `<span class="tag-chip"><span>${label}</span><button type="button" aria-label="Remove ${label}">×</button></span>`;
          tagEntry.querySelector('.tag-chip button').addEventListener('click', () => tagEntry.querySelector('.tag-chip').remove());
        });
      }
    }
    if (params.get('state') === 'tag-combined') {
      const tagEntry = document.querySelector('.tag-entry');
      tagEntry.style.display = 'block';
      tagEntry.innerHTML = '<div class="selected-tags"></div><div class="tag-suggestions"><button type="button" class="tag-suggestion">design</button><button type="button" class="tag-suggestion">reading</button><button type="button" class="tag-suggestion">research</button></div><div class="tag-new-row"><input id="manage-tag" placeholder="Create a new tag"><button type="button" class="tag-add-button">Add</button></div>';
      document.querySelector('#tag-help').textContent = 'Choose an existing tag, or create a new one';
      const selected = tagEntry.querySelector('.selected-tags');
      function selectCombinedTag(label) {
        if ([...selected.querySelectorAll('.tag-chip > span')].some(item => item.textContent === label)) return;
        const chip = document.createElement('span');
        chip.className = 'tag-chip';
        chip.innerHTML = `<span>${label}</span><button type="button" aria-label="Remove ${label}">×</button>`;
        chip.querySelector('button').addEventListener('click', () => chip.remove());
        selected.appendChild(chip);
      }
      for (const button of tagEntry.querySelectorAll('.tag-suggestion')) {
        button.addEventListener('click', () => selectCombinedTag(button.textContent));
      }
      const newInput = tagEntry.querySelector('#manage-tag');
      const addNew = () => {
        const label = newInput.value.trim();
        if (!label) return;
        selectCombinedTag(label);
        newInput.value = '';
      };
      tagEntry.querySelector('.tag-add-button').addEventListener('click', addNew);
      newInput.addEventListener('keydown', event => {
        if (event.key === 'Enter') { event.preventDefault(); addNew(); }
      });
    }
  </script>
</body>
</html>

