      document.querySelector('#tag-help').textContent = 'Choose a suggested tag';
      for (const button of document.querySelectorAll('.tag-suggestion')) {
        button.addEventListener('click', () => {
          const label = button.textContent;
          tagEntry.innerHTML = `<span class="tag-chip"><span>${label}</span><button type="button" aria-label="Remove ${label}">×</button></span>`;
          tagEntry.querySelector('.tag-chip button').addEventListener('click', () => tagEntry.querySelector('.tag-chip').remove());
        });
      }
    }
    if (params.get('state') === 'tag-combined') {
      const tagEntry = document.querySelector('.tag-entry');
      tagEntry.style.display = 'block';
