      document.querySelector('#tag-help').textContent = 'Choose an existing tag, or create a new one';
      const selected = tagEntry.querySelector('.selected-tags');
      function selectCombinedTag(label) {
        if ([...selected.querySelectorAll('.tag-chip > span')].some(item => item.textContent === label)) return;
        const chip = document.createElement('span');
        chip.className = 'tag-chip';
        chip.innerHTML = `<span>${label}</span><button type="button" aria-label="Remove ${label}">×</button>`;
        chip.querySelector('button').addEventListener('click', () => chip.remove());
        selected.appendChild(chip);
      }
      for (const button of tagEntry.querySelectorAll('.tag-suggestion')) {
        button.addEventListener('click', () => selectCombinedTag(button.textContent));
      }
      const newInput = tagEntry.querySelector('#manage-tag');
      const addNew = () => {
        const label = newInput.value.trim();
        if (!label) return;
        selectCombinedTag(label);
        newInput.value = '';
      };
      tagEntry.querySelector('.tag-add-button').addEventListener('click', addNew);
      newInput.addEventListener('keydown', event => {
        if (event.key === 'Enter') { event.preventDefault(); addNew(); }
      });
    }
