const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({headless: true});
  const page = await browser.newPage({viewport: {width: 1440, height: 1000}});
  await page.goto('http://127.0.0.1:4001/?state=read-later-icon', {waitUntil: 'networkidle'});
  const button = page.locator('#readlater-button');
  if ((await button.getAttribute('aria-label')) !== 'Read later') throw new Error('Icon action lacks label');
  await button.click();
  if (!(await button.innerText()).includes('Saved for later')) throw new Error('Icon alternative did not mark bookmark');
  await page.screenshot({path: 'prototypes/read-later-icon-result.png', fullPage: true});
  console.log('Icon Read later alternative passed with the same marked result.');
  await browser.close();
})();
