:root {
  color-scheme: light;
  --ink: #17211c;
  --muted: #66716b;
  --faint: #8f9893;
  --paper: #f5f4ef;
  --panel: #fffefa;
  --line: #dde2dc;
  --green: #225a43;
  --green-deep: #174633;
  --green-soft: #e6f0ea;
  --amber: #a56e1e;
  --amber-soft: #fff2d6;
  --danger: #a23e36;
  --danger-soft: #fff0ed;
  --shadow: 0 18px 55px rgba(28, 45, 36, .09);
}

* { box-sizing: border-box; }
html { min-width: 320px; background: var(--paper); }
body { margin: 0; color: var(--ink); background: radial-gradient(circle at 88% -5%, rgba(210, 157, 66, .11), transparent 30rem), var(--paper); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
button, input, textarea { font: inherit; }
button { cursor: pointer; }
[hidden] { display: none !important; }

.app-shell { min-height: 100vh; display: grid; grid-template-columns: 248px minmax(0, 1fr); }
.sidebar { position: sticky; top: 0; height: 100vh; padding: 31px 22px 24px; display: flex; flex-direction: column; border-right: 1px solid var(--line); background: rgba(255,254,250,.82); backdrop-filter: blur(14px); }
