.nav-glyph { display: inline-grid; place-items: center; width: 19px; height: 19px; }
.collection-glyph { border: 2px solid currentColor; border-radius: 4px; position: relative; }
.collection-glyph::before, .collection-glyph::after { content: ""; position: absolute; left: 3px; right: 3px; height: 2px; background: currentColor; opacity: .65; }
.collection-glyph::before { top: 4px; } .collection-glyph::after { top: 9px; }
.later-glyph { font-size: 22px; line-height: 1; }
.tag-nav { margin-top: 30px; padding-top: 24px; border-top: 1px solid var(--line); min-height: 0; overflow: auto; }
