.form-field input, .form-field textarea, .new-tag-row input { width: 100%; border: 1px solid var(--line); border-radius: 9px; padding: 11px 12px; outline: 0; color: var(--ink); background: white; font-size: 14px; font-weight: 400; resize: vertical; }
.form-field input:focus, .form-field textarea:focus, .new-tag-row input:focus { border-color: #8aab9a; box-shadow: 0 0 0 3px var(--green-soft); }
.selected-tags, .tag-suggestions { display: flex; flex-wrap: wrap; gap: 7px; }
.selected-tags:empty { display: none; }
.selected-tag { display: inline-flex; align-items: center; gap: 5px; padding: 6px 9px; border-radius: 999px; color: var(--green); background: var(--green-soft); font-size: 11px; }
.selected-tag button { padding: 0; border: 0; color: inherit; background: transparent; font-size: 15px; }
.suggestion-tag { padding: 6px 9px; border: 0; border-radius: 999px; color: #556159; background: #eff2ef; font-size: 11px; }
.suggestion-tag:hover { color: var(--green); background: var(--green-soft); }
.new-tag-row { display: flex; gap: 8px; }
.new-tag-row .secondary-button { min-width: 68px; }
.form-field small { min-height: 16px; color: var(--muted); font-weight: 400; }
.form-field small.error { color: var(--danger); }
.form-actions { display: flex; justify-content: flex-end; margin-top: 24px; }
.form-actions .primary-button { padding: 12px 18px; }
.danger-zone { display: flex; justify-content: space-between; align-items: center; gap: 20px; margin-top: 30px; padding-top: 23px; border-top: 1px solid var(--line); }
.danger-zone p { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.5; }
.danger-zone strong { color: var(--ink); font-size: 13px; }
.dialog-backdrop { align-items: center; justify-content: center; padding: 22px; }
.confirm-dialog { width: min(450px, 100%); padding: 27px; border-radius: 16px; background: var(--panel); box-shadow: 0 25px 80px rgba(17,27,21,.25); }
.warning-mark { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%; color: var(--danger); background: var(--danger-soft); font-weight: 900; }
.confirm-dialog h2 { margin: 17px 0 9px; font-family: Georgia, serif; font-size: 26px; font-weight: 500; }
.confirm-dialog p { margin: 0; color: var(--muted); font-size: 13px; line-height: 1.55; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 9px; margin-top: 24px; }

@media (max-width: 850px) {
  .app-shell { grid-template-columns: 1fr; }
  .sidebar { position: static; width: 100%; height: auto; padding: 20px; border-right: 0; border-bottom: 1px solid var(--line); }
  .brand { margin-bottom: 18px; }
  .primary-nav { grid-template-columns: 1fr 1fr; margin-top: 0; }
  .tag-nav, .sidebar-foot { display: none; }
  .main { padding: 27px 20px 60px; }
}

@media (max-width: 650px) {
  .capture-promise { display: none; }
  .library-toolbar { align-items: stretch; flex-direction: column; }
  .search-field { width: 100%; }
  .bookmark-card { grid-template-columns: 76px minmax(0, 1fr); }
  .card-image { width: 76px; height: 76px; }
  .card-actions { grid-column: 1 / -1; grid-template-columns: 1fr 1fr; }
  .preview-row { grid-template-columns: 58px 1fr; }
  .preview-image { width: 58px; height: 56px; }
  .preview-row > .primary-button { grid-column: 1 / -1; }
  .danger-zone { align-items: stretch; flex-direction: column; }
  .danger-zone .danger-button { width: 100%; }
}

