* { box-sizing: border-box; }
body { margin: 0; color: #20241f; background: #fffdf8; font-family: Georgia, "Times New Roman", serif; }
.saved-banner { display: flex; justify-content: space-between; gap: 20px; padding: 13px 6vw; color: #684712; background: #fff0cf; font: 13px Inter, system-ui, sans-serif; }
.saved-banner strong { font-weight: 800; }
.reader-head { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 22px 6vw; border-bottom: 1px solid #dfdcd3; color: #706d66; font: 13px Inter, system-ui, sans-serif; }
.reader-brand { display: flex; align-items: center; gap: 9px; color: #1d2b24; text-decoration: none; font-size: 18px; font-weight: 800; }
.reader-brand span { width: 29px; height: 29px; display: grid; place-items: center; border-radius: 7px; color: white; background: #225a43; font-family: Georgia, serif; }
#reader { max-width: 760px; margin: 72px auto; padding: 0 27px 100px; }
.source-line { color: #936127; font: 800 11px Inter, system-ui, sans-serif; letter-spacing: .13em; text-transform: uppercase; }
h1 { margin: 17px 0 21px; font-size: clamp(48px, 7vw, 76px); line-height: 1; letter-spacing: -.045em; font-weight: 500; }
.description { margin: 0 0 28px; color: #5b5a54; font-size: 21px; line-height: 1.5; }
.meta { padding-top: 19px; border-top: 1px solid #dfdcd3; color: #77736c; font: 12px Inter, system-ui, sans-serif; }
.article-body { margin-top: 48px; font-size: 19px; line-height: 1.78; }
.article-body p { margin: 0 0 1.4em; }
.article-body p:first-child::first-letter { float: left; margin: 8px 8px 0 0; color: #936127; font-size: 62px; line-height: .72; }
.loading, .reader-error { padding: 40px; border: 1px dashed #d2cfc6; border-radius: 14px; color: #77736c; text-align: center; font: 15px Inter, system-ui, sans-serif; }

