} catch (error) {
  showNotice('Trove could not load your library. Refresh to try again.', 'danger');
}

setInterval(() => {
  if (state.bookmarks.some(item => item.archive?.status === 'pending') && elements.editBackdrop.hidden) loadBookmarks().catch(() => {});
