import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import {
  allKnownTags,
  applyCapturedPage,
  canonicalizeUrl,
  createBookmark,
  fetchPage,
  matchesSearch,
  parseWebUrl,
  sourceFromUrl,
