:root {
  color-scheme: light;
  --ink: #17211c;
  --muted: #66716b;
  --faint: #8f9893;
  --paper: #f5f4ef;
  --panel: #fffefa;
  --line: #dde2dc;
  --green: #225a43;
  --green-deep: #174633;
  --green-soft: #e6f0ea;
  --amber: #a56e1e;
  --amber-soft: #fff2d6;
  --danger: #a23e36;
  --danger-soft: #fff0ed;
  --shadow: 0 18px 55px rgba(28, 45, 36, .09);
}

* { box-sizing: border-box; }
html { min-width: 320px; background: var(--paper); }
body { margin: 0; color: var(--ink); background: radial-gradient(circle at 88% -5%, rgba(210, 157, 66, .11), transparent 30rem), var(--paper); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
button, input, textarea { font: inherit; }
button { cursor: pointer; }
[hidden] { display: none !important; }

.app-shell { min-height: 100vh; display: grid; grid-template-columns: 248px minmax(0, 1fr); }
.sidebar { position: sticky; top: 0; height: 100vh; padding: 31px 22px 24px; display: flex; flex-direction: column; border-right: 1px solid var(--line); background: rgba(255,254,250,.82); backdrop-filter: blur(14px); }
.brand { display: inline-flex; align-items: center; gap: 11px; align-self: flex-start; color: var(--ink); text-decoration: none; font-size: 21px; font-weight: 800; letter-spacing: -.035em; }
.brand-mark { width: 31px; height: 35px; border-radius: 8px 8px 4px 4px; background: var(--green); position: relative; }
.brand-mark::after { content: ""; position: absolute; left: 7px; bottom: -1px; border-left: 8.5px solid transparent; border-right: 8.5px solid transparent; border-bottom: 8px solid var(--panel); }
.primary-nav { display: grid; gap: 6px; margin-top: 50px; }
.nav-button { width: 100%; display: grid; grid-template-columns: 20px 1fr auto; align-items: center; gap: 10px; padding: 11px 12px; border: 0; border-radius: 10px; color: var(--muted); background: transparent; text-align: left; font-size: 14px; font-weight: 650; }
.nav-button:hover { background: #eff2ee; color: var(--ink); }
.nav-button.active { color: var(--green); background: var(--green-soft); }
.nav-count { min-width: 22px; padding: 2px 6px; border-radius: 999px; background: rgba(24,68,50,.08); text-align: center; font-size: 11px; }
.nav-glyph { display: inline-grid; place-items: center; width: 19px; height: 19px; }
.collection-glyph { border: 2px solid currentColor; border-radius: 4px; position: relative; }
.collection-glyph::before, .collection-glyph::after { content: ""; position: absolute; left: 3px; right: 3px; height: 2px; background: currentColor; opacity: .65; }
.collection-glyph::before { top: 4px; } .collection-glyph::after { top: 9px; }
.later-glyph { font-size: 22px; line-height: 1; }
.tag-nav { margin-top: 30px; padding-top: 24px; border-top: 1px solid var(--line); min-height: 0; overflow: auto; }
.section-label { padding: 0 10px 9px; color: var(--faint); font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.tag-list { display: grid; gap: 3px; }
.tag-filter-button { width: 100%; display: flex; justify-content: space-between; gap: 10px; padding: 8px 10px; border: 0; border-radius: 8px; background: transparent; color: var(--muted); text-align: left; font-size: 13px; }
.tag-filter-button:hover, .tag-filter-button.active { background: var(--green-soft); color: var(--green); }
.sidebar-foot { margin-top: auto; padding: 18px 9px 0; color: var(--faint); font-size: 11px; }
.status-dot { display: inline-block; width: 7px; height: 7px; margin-right: 7px; border-radius: 50%; background: #54a376; }

.main { padding: 34px clamp(26px, 5vw, 74px) 80px; min-width: 0; }
.page-head { max-width: 1100px; margin: 0 auto; display: flex; justify-content: space-between; align-items: start; gap: 24px; }
.eyebrow { margin: 0 0 8px; color: var(--green); font-size: 11px; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; }
h1, h2, h3, p { overflow-wrap: anywhere; }
.page-head h1 { margin: 0; font-family: Georgia, "Times New Roman", serif; font-size: clamp(34px, 4.5vw, 53px); line-height: 1.03; font-weight: 500; letter-spacing: -.04em; }
.avatar { width: 38px; height: 38px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%; background: #eee2ce; color: #74582d; font-size: 12px; font-weight: 800; }

.save-panel { max-width: 1100px; margin: 36px auto 0; padding: 21px; border: 1px solid var(--line); border-radius: 17px; background: rgba(255,254,250,.93); box-shadow: var(--shadow); }
.save-heading-row { display: flex; justify-content: space-between; gap: 20px; align-items: start; margin-bottom: 16px; }
.save-heading-row h2 { margin: 0 0 4px; font-family: Georgia, serif; font-size: 24px; font-weight: 500; }
.save-heading-row p { margin: 0; color: var(--muted); font-size: 13px; }
.capture-promise { padding: 6px 9px; border-radius: 999px; color: var(--green); background: var(--green-soft); font-size: 11px; font-weight: 750; white-space: nowrap; }
.url-field { min-height: 55px; display: flex; align-items: center; gap: 11px; padding: 0 14px; border: 1px solid var(--line); border-radius: 12px; background: white; transition: border-color .15s, box-shadow .15s; }
.url-field:focus-within { border-color: #8aab9a; box-shadow: 0 0 0 3px var(--green-soft); }
.url-field svg { width: 21px; color: var(--muted); flex: 0 0 auto; }
.url-field input { width: 100%; min-width: 0; padding: 15px 0; border: 0; outline: 0; color: var(--ink); background: transparent; }
.url-field input::placeholder, .search-field input::placeholder { color: #99a19d; }
.url-status { width: 17px; height: 17px; flex: 0 0 auto; }
.url-status.loading { border: 2px solid #d7ded9; border-top-color: var(--green); border-radius: 50%; animation: spin .75s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
#save-result:empty { display: none; }
.save-result { margin-top: 13px; padding: 15px; border-radius: 12px; background: #f6f8f5; animation: rise .22s ease-out; }
@keyframes rise { from { opacity: 0; transform: translateY(4px); } }
.save-result.error { color: #8e3b34; background: var(--danger-soft); }
.save-result.warning { color: #704d18; background: var(--amber-soft); }
.result-title { margin: 0 0 4px; font-family: Georgia, serif; font-size: 19px; font-weight: 500; }
.result-copy { margin: 0; color: var(--muted); font-size: 13px; line-height: 1.5; }
.preview-row { display: grid; grid-template-columns: 72px 1fr auto; gap: 14px; align-items: center; }
.preview-image, .card-image { overflow: hidden; position: relative; background: linear-gradient(145deg, #f2e4ca, #d6eadf); }
.preview-image { width: 72px; height: 64px; border-radius: 9px; }
.preview-image img, .card-image img { width: 100%; height: 100%; object-fit: cover; }
.preview-image::after, .card-image::after { content: "Aa"; position: absolute; inset: 0; display: grid; place-items: center; color: var(--green); font-family: Georgia, serif; font-size: 22px; z-index: 0; }
.preview-image img, .card-image img { position: relative; z-index: 1; }
.source-line { display: flex; align-items: center; gap: 7px; margin-bottom: 5px; color: var(--muted); font-size: 11px; }
.source-icon { width: 19px; height: 19px; display: grid; place-items: center; overflow: hidden; border-radius: 5px; background: #1d2b24; color: white; font-family: Georgia, serif; font-size: 11px; font-weight: bold; }
.source-icon img { width: 100%; height: 100%; object-fit: cover; }
.result-actions { display: flex; flex-wrap: wrap; gap: 9px; margin-top: 14px; }

.notice { max-width: 1100px; display: none; align-items: center; gap: 10px; margin: 18px auto -4px; padding: 13px 15px; border-radius: 11px; color: var(--green); background: var(--green-soft); font-size: 13px; font-weight: 700; }
.notice.show { display: flex; }
.notice.danger { color: var(--danger); background: var(--danger-soft); }
.notice::before { content: "✓"; width: 23px; height: 23px; display: grid; place-items: center; border-radius: 50%; background: rgba(34,90,67,.1); }

.library-section { max-width: 1100px; margin: 48px auto 0; }
.library-toolbar { display: flex; justify-content: space-between; align-items: end; gap: 24px; }
